import sys

def main():
    n = int(sys.stdin.read().split()[0])
    if n < 2:
        print("Not Prime")
        return
    if n < 4:
        print("Prime")
        return
    if n % 2 == 0 or n % 3 == 0:
        print("Not Prime")
        return
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            print("Not Prime")
            return
        i += 6
    print("Prime")

