def gen(rng):
    def isp(n):
        if n < 2:
            return False
        i = 2
        while i * i <= n:
            if n % i == 0:
                return False
            i += 1
        return True

    def prev_prime(n):
        while not isp(n):
            n -= 1
        return n

    p1 = prev_prime(10**6)
    p2 = prev_prime(p1 - 1)
    big_prime = prev_prime(10**12)
    tests = []
    for v in (1, 2, 3, 4, 5, 9, 25, 49, 97, 100, 7919, 10**6, 10**12 - 1, 10**12):
        tests.append(str(v))
    for _ in range(8):
        tests.append(str(rng.randint(1, 300)))
    tests.append(str(big_prime))
    tests.append(str(p1 * p2))
    tests.append(str(p1 * p1))
    tests.append(str(big_prime - 2 if isp(big_prime - 2) else prev_prime(big_prime - 1)))
    tests.append(str(2 * prev_prime(5 * 10**11 - 1)))
    return tests

